#[serde(deny_unknown_fields)]
pub struct ItemQuery {
    /// Absent means every kind.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub kinds: Option<Vec<ItemKind>>,
    /// Absent means every source the caller may read.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sources: Option<Vec<SourceSelector>>,
    /// Full-text search over title, body and the kinds' text fields.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub text: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub r#where: Option<Vec<ItemCondition>>,
    /// The first entry sorts first; absent is updatedAt, newest first.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sort: Option<Vec<ItemSort>>,
    /// The cursor of the previous ItemPage, to read the next one. Opaque.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cursor: Option<String>,
    /// Items per page: 50 when absent, 500 at most.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub limit: Option<u64>,
}

